<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_admin();$page_title='Lead Sources';$current_page='sources';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='add'){$name=trim($_POST['name']??'');if($name==='')$error='Source name is required.';else{try{$s=$pdo->prepare('INSERT INTO lead_sources(name) VALUES(?)');$s->execute([$name]);flash('success','Lead source added.');redirect('sources.php');}catch(PDOException $e){$error='This source already exists.';}}}elseif($action==='toggle'&&$id){$pdo->prepare('UPDATE lead_sources SET is_active=1-is_active WHERE id=?')->execute([$id]);flash('success','Source status updated.');redirect('sources.php');}}
$rows=$pdo->query('SELECT s.*,COUNT(l.id) lead_count FROM lead_sources s LEFT JOIN leads l ON l.source_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();require __DIR__.'/../includes/header.php';if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><div class="detail-grid"><div class="section-card"><div class="section-head"><h2>Lead Sources</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>Source</th><th>Leads</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=($r['lead_count'])?></td><td><span class="badge <?=$r['is_active']?'badge-green':'badge-gray'?>"><?=$r['is_active']?'Active':'Inactive'?></span></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-light btn-sm"><?=$r['is_active']?'Deactivate':'Activate'?></button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="section-card form-card"><h2 style="margin-top:0">Add Lead Source</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="field"><label>Source Name</label><input class="form-control" name="name" placeholder="e.g. Referral" required></div><div class="form-actions"><button class="btn btn-primary">Add Source</button></div></form></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
